/**
 * NAF MedAssist Vending Machine Engine - Pure AI Matching
 */
const CHANNEL = 'chat';
const SOURCE_EMA = 'https://www.ema.europa.eu';
const SOURCE_AMMPS = 'https://ammps.gov.ma/';
const SOURCE_NHS = 'https://www.nhs.uk/medicines/';
const NUMBERS = '112 (Europe/EEA), 15 (Morocco), 911 (US/Canada)';
const MAX_SELF_CARE_DAYS = 3;
const MAX_TURNS = 35;

const ALLOWED_EMERGENCY_SIGNALS = [
  'sudden_extreme_headache', 'unilateral_severe_retro_orbital', 'neurological_symptoms',
  'breathing_difficulty', 'chest_pain_or_pressure', 'possible_severe_allergic_reaction',
  'possible_overdose', 'fever_and_stiff_neck', 'severe_neurological_warning',
  'serious_bleeding', 'self_harm_or_suicidal', 'patient_confirmed_red_flag'
];

function normalized(text) {
  return String(text ?? '').normalize('NFKC')
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u0660-\u0669]/g, d => String(d.charCodeAt(0) - 0x0660))
    .normalize('NFD').replace(/\p{M}/gu, '')
    .toLowerCase().replace(/\s+/g, ' ').trim();
}
function uniq(a) { return [...new Set(a)]; }
function cleanText(v, n) { return String(v ?? '').replace(/[<>\u0000-\u001f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n); }

function fallbackYes(t) { return /^(?:yes|yeah|yep|yup|correct|right|sure|ok|okay|oui|ouais|d'accord|ja|si|claro|نعم|ايوه|اه|موافق)(?=$|[\s,.!?;:])/i.test(t); }
function fallbackNo(t) { return /^(?:no|nope|nah|none|nothing|not applicable|n\/a|non|nein|nada|لا|بدون)(?=$|[\s,.!?;:])/i.test(t); }

function resolveMedicine(st, facts) {
  // Pure AI matching logic based on the inventory provided in the prompt
  if (facts && facts.recommendedMedicine) {
    return {
      name: cleanText(facts.recommendedMedicine, 120),
      category: cleanText(facts.medicineCategory || 'OTC Medicine', 80),
      dosage: cleanText(facts.dosage || 'Take as directed.', 250),
      safetyNotes: cleanText(facts.safetyNotes || 'Consult a healthcare provider.', 250)
    };
  }
  if (st.recommendedMedicine) {
    return { name: st.recommendedMedicine, category: st.medicineCategory, dosage: st.dosage, safetyNotes: st.safetyNotes };
  }
  return { name: 'Pending AI Match', category: 'N/A', dosage: 'N/A', safetyNotes: 'N/A' };
}

function parseFacts(agent) {
  const out = agent && agent.output;
  if (out && typeof out === 'object' && !Array.isArray(out)) return out;
  if (typeof out !== 'string') return null;
  const t = out.replace(/```json/g, '').replace(/```/g, '').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a < 0 || b <= a) return null;
  try { return JSON.parse(t.slice(a, b + 1)); } catch (e) { return null; }
}

function cleanFacts(f) {
  const o = {};
  if (!f || typeof f !== 'object' || Array.isArray(f)) return o;
  const int = (v, lo, hi) => {
    const n = typeof v === 'string' && /^\d+$/.test(v.trim()) ? Number(v) : v;
    return Number.isInteger(n) && n >= lo && n <= hi ? n : undefined;
  };

  if (typeof f.patientQuestionAnswer === 'string') o.patientQuestionAnswer = cleanText(f.patientQuestionAnswer, 300);

  const qr = f.quickReplies || f.suggestions || f.buttons;
  if (Array.isArray(qr)) {
    o.quickReplies = qr
      .map(v => typeof v === 'string' ? v : (v && typeof v === 'object' && v.text ? v.text : ''))
      .map(v => cleanText(v, 60))
      .filter(Boolean)
      .slice(0, 6);
  }

  const age = int(f.age, 0, 120); if (age !== undefined) o.age = age;
  const sv = int(f.severity, 1, 10); if (sv !== undefined) o.severity = sv;
  if (typeof f.weightKg === 'number' && Number.isFinite(f.weightKg) && f.weightKg >= 2 && f.weightKg <= 300) o.weightKg = Math.round(f.weightKg * 10) / 10;
  if (typeof f.durationDays === 'number' && Number.isFinite(f.durationDays) && f.durationDays >= 0 && f.durationDays <= 36500) o.durationDays = Math.round(f.durationDays * 100) / 100;
  if (typeof f.symptom === 'string' && f.symptom.trim()) o.symptom = cleanText(f.symptom, 150);
  if (typeof f.duration === 'string' && f.duration.trim()) o.duration = cleanText(f.duration, 120);
  if (f.onset === 'sudden' || f.onset === 'gradual') o.onset = f.onset;
  if (typeof f.worsening === 'boolean') o.worsening = f.worsening;
  if (typeof f.patientIsChild === 'boolean') o.patientIsChild = f.patientIsChild;
  if (['yes', 'no'].includes(f.affirmation)) o.affirmation = f.affirmation;
  if (['yes', 'no', 'not_applicable'].includes(f.pregnancy)) o.pregnancy = f.pregnancy;
  if (['none', 'occasional', 'regular'].includes(f.alcohol)) o.alcohol = f.alcohol;

  for (const k of ['conditions', 'medications', 'allergies']) {
    if (Array.isArray(f[k])) o[k] = f[k].filter(v => typeof v === 'string').map(v => cleanText(v, 90)).filter(Boolean).slice(0, 12);
  }

  if (typeof f.emergency === 'boolean') o.emergency = f.emergency;
  if (Array.isArray(f.emergencySignals)) {
    o.emergencySignals = uniq(f.emergencySignals.filter(v => typeof v === 'string' && ALLOWED_EMERGENCY_SIGNALS.includes(v)));
    if (o.emergencySignals.length > 0) o.emergency = true;
  }

  if (typeof f.isSafeOtc === 'boolean') o.isSafeOtc = f.isSafeOtc;
  if (typeof f.recommendedMedicine === 'string') o.recommendedMedicine = cleanText(f.recommendedMedicine, 120);
  if (typeof f.medicineCategory === 'string') o.medicineCategory = cleanText(f.medicineCategory, 80);
  if (typeof f.dosage === 'string') o.dosage = cleanText(f.dosage, 250);
  if (typeof f.safetyNotes === 'string') o.safetyNotes = cleanText(f.safetyNotes, 250);
  if (typeof f.referralReason === 'string') o.referralReason = cleanText(f.referralReason, 250);
  return o;
}

function blockers(s) {
  const r = [];
  if (s.patientIsChild || (s.age !== null && s.age < 18)) r.push('vending machine automated dispensing is restricted to adults aged 18 and older');
  if (s.pregnancy === 'yes') r.push('automated dispensing is not approved during pregnancy or breastfeeding without a doctor\'s prescription');
  if (s.severity !== null && s.severity >= 8) r.push('your reported symptom is severe (8/10 or higher)');
  if (s.worsening === true) r.push('your symptoms are actively getting worse');
  if (s.caseData && typeof s.caseData.durationDays === 'number' && s.caseData.durationDays >= MAX_SELF_CARE_DAYS) r.push('your symptom has lasted more than ' + MAX_SELF_CARE_DAYS + ' days');

  if (s.isSafeOtc === false && s.referralReason) r.push(s.referralReason);

  // JS Double-Check for Allergies (if AI misses the interaction)
  if (s.recommendedMedicine && Array.isArray(s.allergies) && s.allergies.length > 0) {
    const medName = s.recommendedMedicine.toLowerCase();
    if (s.allergies.some(a => medName.includes(a.toLowerCase()))) {
      r.push('a potential allergy conflict was detected with the machine inventory');
    }
  }

  // Ensure AI successfully mapped to inventory before dispensing
  if (!s.recommendedMedicine && s.lastQuestion === 'summary_confirmation' && s.isSafeOtc !== false) {
    r.push('the AI could not confidently match your symptom to our available inventory');
  }

  return uniq(r);
}

function missingHistory(s) {
  const m = [];
  if (!Array.isArray(s.allergies)) m.push('allergies');
  if (!Array.isArray(s.conditions)) m.push('conditions');
  if (!Array.isArray(s.medications)) m.push('medications');
  return m;
}

const req = $('Safety Screen6').first().json;
const agent = $input.first().json || {};
const factsRaw = parseFacts(agent);
const facts = cleanFacts(factsRaw);
const AI_STATUS = agent.error ? 'MODEL_UNAVAILABLE_FALLBACK' : (factsRaw ? 'MODEL_RESPONSE_RECEIVED' : 'MODEL_RESPONSE_UNPARSEABLE');
let s = req.state || {};
const msg = String(req.message || '').trim();
const text = normalized(msg);
s.turns = (s.turns || 0) + 1;

const isYes = facts.affirmation === 'yes' || fallbackYes(text);
const isNo = facts.affirmation === 'no' || fallbackNo(text);

function out(stage, reply, speakText, st, extra) {
  return [{
    json: Object.assign({
      reply,
      speakText: speakText || reply,
      stage,
      channel: CHANNEL,
      state: st,
      summary: null,
      decision: null,
      sources: [SOURCE_EMA, SOURCE_AMMPS],
      requiresReview: false,
      demoOnly: true,
      aiStatus: AI_STATUS,
      quickReplies: (extra && Array.isArray(extra.quickReplies)) ? extra.quickReplies : (facts.quickReplies || [])
    }, extra || {})
  }];
}

function makeSummary(st) {
  const list = v => (!v || !Array.isArray(v) || !v.length) ? 'None reported' : v.join(', ');
  const med = resolveMedicine(st, facts);
  return {
    age: st.age === null ? 'Adult (standard)' : `${st.age} years`,
    symptom: st.symptom || 'Not provided',
    duration: st.duration || 'Short term (< 3 days)',
    onset: st.onset || 'Gradual',
    severity: st.severity === null ? 'Mild / Moderate' : `${st.severity}/10`,
    conditions: list(st.conditions),
    medications: list(st.medications),
    allergies: list(st.allergies),
    emergencyScreen: st.redFlagsCleared === true ? 'Cleared' : 'Pending evaluation',
    additionalContext: `Vending Care for ${med.name}`
  };
}

const PROMPTS = {
  consent: ['Welcome to NAF MedAssist! I can evaluate symptoms and dispense safe over-the-counter medication. May I ask you a few screening questions first?'],
  consent_retry: ['Please say yes to continue with medicine dispensing.'],
  symptom: ['What symptom or medical issue are you experiencing today?'],
  age: ['To ensure the dosage is safe, how old are you in years?'],
  age_retry: ['Please state your age in numbers (e.g., 30).'],
  duration: ['How long have you had this symptom?'],
  severity: ['On a scale of 1 to 10, how severe is it (1 = very mild, 10 = worst possible)?'],
  severity_retry: ['Please provide a number from 1 to 10.'],
  redflags: ['Quick safety check: Do you have chest pain, shortness of breath, sudden weakness, confusion, or a severe sudden headache? (Yes or No)'],
  redflags_retry: ['Please answer yes or no: Do you have any of those severe warning signs?']
};

function ask(promptKey, prefix) {
  const p = PROMPTS[promptKey];
  const stage = promptKey.startsWith('consent') ? 'CONSENT' : 'QUESTION';

  let aiAnswer = '';
  if (facts.patientQuestionAnswer) {
      aiAnswer = facts.patientQuestionAnswer + "\n\n";
  }

  return out(stage, aiAnswer + (prefix || '') + p[0], aiAnswer + (prefix || '') + p[0], s);
}

function askHistory(missing, followUp) {
  let aiAnswer = facts.patientQuestionAnswer ? facts.patientQuestionAnswer + "\n\n" : '';
  const reply = followUp
    ? `${aiAnswer}Almost ready! Do you have any medicine allergies, chronic health conditions, or current medications? You can simply say "none".`
    : `${aiAnswer}Before dispensing, do you have any medicine allergies, chronic conditions, or other medicines you take? (You can say "none").`;
  return out('QUESTION', reply, reply, s);
}

function summaryOut(prefix) {
  const sum = makeSummary(s);
  const med = resolveMedicine(s, facts);
  const reply = (prefix || '') + `Summary for Vending Dispensing:\n\n` +
    `• Symptom: ${sum.symptom}\n` +
    `• Recommended: 💊 ${med.name}\n` +
    `• Dosage: ${med.dosage}\n` +
    `• Age: ${sum.age} | Severity: ${sum.severity}\n` +
    `• Allergies/Conditions: ${sum.allergies}, ${sum.conditions}\n\n` +
    `Is this correct? Say yes to confirm and dispense.`;
  return out('SUMMARY_CONFIRM', reply, reply, s, { summary: sum });
}

function finishEmergency(signals) {
  s.redFlagsCleared = false; s.completed = true; s.outcome = 'EMERGENCY'; s.lastQuestion = 'done';
  const reply = 'EMERGENCY ALERT: Your symptoms indicate a potential medical emergency. Automated dispensing is locked. Please call ' + NUMBERS + ' or seek immediate care.';
  return out('EMERGENCY', reply, reply, s, { requiresReview: true, quickReplies: [] });
}

function finishRefer(reasons) {
  s.completed = true; s.outcome = 'PROFESSIONAL_REVIEW'; s.lastQuestion = 'done';
  const reply = 'Assessment completed. Over-the-counter medicine cannot be dispensed automatically because:\n' +
    reasons.map(r => '• ' + r).join('\n') +
    '\n\nPlease consult a pharmacist or doctor.';
  return out('RESULT', reply, reply, s, { requiresReview: true, quickReplies: [] });
}

function finishOtc() {
  const med = resolveMedicine(s, facts);
  s.summaryConfirmed = true; s.completed = true; s.outcome = 'OTC_INFORMATION'; s.lastQuestion = 'done';
  const reply = `Assessment completed. Safety screening cleared!\n\n` +
    `💊 **${med.name}**\n` +
    `• Category: ${med.category}\n` +
    `• Dosage: ${med.dosage}\n` +
    `• Safety: ${med.safetyNotes}\n\n` +
    `Please process payment to collect your medication from the tray below.`;
  return out('RESULT', reply, reply, s, { requiresReview: false, maxQuantity: 1, quickReplies: [] });
}

function absorbFacts() {
  if (facts.patientIsChild === true) s.patientIsChild = true;
  if (!s.symptom && facts.symptom) s.symptom = facts.symptom;
  if (s.age === null && facts.age !== undefined) s.age = facts.age;
  if (!s.duration && facts.duration) s.duration = facts.duration;
  if (facts.durationDays !== undefined) s.caseData = Object.assign({}, s.caseData, { durationDays: facts.durationDays });
  if (!s.onset && facts.onset) s.onset = facts.onset;
  if (s.severity === null && facts.severity !== undefined) s.severity = facts.severity;
  if (s.worsening === null && facts.worsening !== undefined) s.worsening = facts.worsening;

  if (facts.recommendedMedicine) s.recommendedMedicine = facts.recommendedMedicine;
  if (facts.medicineCategory) s.medicineCategory = facts.medicineCategory;
  if (facts.dosage) s.dosage = facts.dosage;
  if (facts.safetyNotes) s.safetyNotes = facts.safetyNotes;
  if (facts.isSafeOtc !== undefined) s.isSafeOtc = facts.isSafeOtc;
  if (facts.referralReason) s.referralReason = facts.referralReason;

  for (const k of ['conditions', 'medications', 'allergies']) {
    if (Array.isArray(facts[k])) {
      if (facts[k].length === 0) s[k] = [];
      else s[k] = uniq((Array.isArray(s[k]) ? s[k] : []).concat(facts[k])).slice(0, 12);
    }
  }
}

function advance() {
  const reasons = blockers(s);
  if (reasons.length) return finishRefer(reasons);

  let next;
  if (s.age === null) next = 'age';
  else if (!s.duration) next = 'duration';
  else if (s.severity === null) next = 'severity';
  else if (s.redFlagsCleared !== true) next = 'redflags';
  else {
    const miss = missingHistory(s);
    if (miss.length) {
      if ((s.topicStep || 0) >= 2) {
        if (!Array.isArray(s.allergies)) s.allergies = [];
        if (!Array.isArray(s.conditions)) s.conditions = [];
        if (!Array.isArray(s.medications)) s.medications = [];
        return summaryOut('');
      }
      s.lastQuestion = 'history';
      return askHistory(miss, (s.topicStep || 0) > 0);
    }
    next = 'summary_confirmation';
  }
  s.lastQuestion = next;
  return next === 'summary_confirmation' ? summaryOut('') : ask(next, '');
}

if (req.reset || !s.lastQuestion) {
  s.lastQuestion = 'consent';
  return ask('consent', '');
}

if (s.turns > MAX_TURNS) return out('COMPLETE', 'Session limit reached. Please consult a pharmacist.', 'Limit reached.', s, { quickReplies: [] });

if (facts.emergency === true || (Array.isArray(facts.emergencySignals) && facts.emergencySignals.length > 0)) return finishEmergency(facts.emergencySignals);
if (s.lastQuestion === 'redflags' && isYes) return finishEmergency(['patient_confirmed_red_flag']);

if (!msg) {
  const again = { consent: 'consent_retry', symptom: 'symptom', age: 'age', duration: 'duration', severity: 'severity', redflags: 'redflags_retry' }[s.lastQuestion];
  if (again) return ask(again, 'Sorry, I did not catch that. ');
  if (s.lastQuestion === 'history') return askHistory(missingHistory(s), true);
  if (s.lastQuestion === 'summary_confirmation') return summaryOut('Sorry, I did not catch that. ');
}

switch (s.lastQuestion) {
  case 'consent':
    if (isYes) { s.consent = true; s.lastQuestion = 'symptom'; return ask('symptom', ''); }
    if (isNo) return out('COMPLETE', 'Understood. Goodbye.', 'Goodbye.', s, { quickReplies: [] });
    if (facts.symptom || text.length > 5) { s.consent = true; absorbFacts(); if (!s.symptom) s.symptom = cleanText(msg, 150); return advance(); }
    return ask('consent_retry', '');
  case 'symptom': absorbFacts(); if (!s.symptom) s.symptom = cleanText(msg, 150); return advance();
  case 'age': absorbFacts(); if (s.age === null) { const num = text.match(/\b(\d{1,3})\b/); if (num) s.age = Number(num[1]); else return ask('age_retry', ''); } return advance();
  case 'duration': absorbFacts(); if (!s.duration) s.duration = cleanText(msg, 120); return advance();
  case 'severity': absorbFacts(); if (s.severity === null) { const num = text.match(/\b([1-9]|10)\b/); if (num) s.severity = Number(num[1]); else if (/mild/i.test(text)) s.severity = 3; else if (/moderate/i.test(text)) s.severity = 5; else if (/severe/i.test(text)) s.severity = 8; else return ask('severity_retry', ''); } return advance();
  case 'redflags': if (isNo) { s.redFlagsCleared = true; return advance(); } return ask('redflags_retry', '');
  case 'history': absorbFacts(); if (isNo || /none|healthy/i.test(text)) { s.allergies = []; s.conditions = []; s.medications = []; } s.topicStep = (s.topicStep || 0) + 1; return advance();
  case 'summary_confirmation':
    if (isYes) return finishOtc();
    if (isNo) { s = { turns: s.turns }; s.lastQuestion = 'age'; return ask('age', 'Let us verify your details again. '); }
    return summaryOut('Please answer yes to dispense. ');
  default: s.lastQuestion = 'consent'; return ask('consent', '');
}

/**
 * NAF MedAssist chat turn - input & state sanitising (runs BEFORE the AI agent).
 * Prepares the session context and formats the clinical extraction prompt.
 */
const CHANNEL = 'chat';
const TIMEOUT_MS = 120000; // 120 seconds public terminal privacy wipe
const STAGES = ['consent', 'symptom', 'age', 'duration', 'severity', 'redflags', 'history', 'summary_confirmation', 'done'];
const LEGACY_STAGES = { combined_severity: 'severity', combined_history: 'history', medical_history: 'history' };
const CASE_KEYS = ['fever','blood','drinking','alert','woundDirty','woundDeep','bleedingStopped','tetanusYears','tylenolStrength','driving','canDrink','breathing','painPersistent','pregnancyPossible','priorUlcer','doseUncertain','needsIngredientCheck','weightReported','adultTabletsOffered','eyeVisionNormal','historyRisk','durationDays'];

function newState() {
  return {
    version: 2, consent: false, symptom: null, mildHint: false,
    topic: null, topicStep: 0, caseData: {}, patientIsChild: false,
    age: null, duration: null, onset: null, severity: null, worsening: null,
    redFlagsCleared: null, conditions: null, medications: null, allergies: null,
    pregnancy: null, weightKg: null, alcohol: null, selfCare: null,
    bpChecked: null, lastQuestion: 'consent', summaryConfirmed: false,
    completed: false, outcome: null, turns: 0, lastActiveTimestamp: Date.now()
  };
}

const inRange = (v, lo, hi, int) => typeof v === 'number' && Number.isFinite(v) && v >= lo && v <= hi && (!int || Number.isInteger(v));

function sanitizeState(raw) {
  const clean = newState();
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return clean;

  // Hardware Privacy Check: Automatically wipe previous patient data if left idle for 2 minutes
  if (raw.lastActiveTimestamp && (Date.now() - raw.lastActiveTimestamp > TIMEOUT_MS)) {
      return clean;
  }

  for (const key of Object.keys(clean)) {
    const value = raw[key];
    if (value === undefined || key === 'version' || key === 'lastActiveTimestamp') continue;
    if (key === 'caseData') {
      if (value && typeof value === 'object' && !Array.isArray(value)) {
        const out = {};
        for (const k of CASE_KEYS) {
          const v = value[k];
          if (typeof v === 'boolean' || (typeof v === 'string' && v.length < 120) || (typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 36500)) out[k] = v;
        }
        clean.caseData = out;
      }
    } else if (['consent', 'mildHint', 'summaryConfirmed', 'completed', 'patientIsChild'].includes(key)) {
      if (typeof value === 'boolean') clean[key] = value;
    } else if (key === 'age') { if (inRange(value, 0, 120, true)) clean.age = value; }
    else if (key === 'severity') { if (inRange(value, 1, 10, true)) clean.severity = value; }
    else if (key === 'weightKg') { if (inRange(value, 2, 300)) clean.weightKg = value; }
    else if (key === 'turns') { if (inRange(value, 0, 200, true)) clean.turns = value; }
    else if (key === 'topicStep') { if (inRange(value, 0, 20, true)) clean.topicStep = value; }
    else if (['worsening', 'redFlagsCleared', 'bpChecked'].includes(key)) {
      if (typeof value === 'boolean' || value === null) clean[key] = value;
    } else if (['conditions', 'medications', 'allergies'].includes(key)) {
      if (Array.isArray(value)) clean[key] = value.filter(v => typeof v === 'string').slice(0, 12).map(v => v.slice(0, 90));
      else if (value === null) clean[key] = null;
    } else if (key === 'lastQuestion') {
      const v = LEGACY_STAGES[value] || value;
      if (STAGES.includes(v)) clean.lastQuestion = v;
    } else if (key === 'pregnancy') { if (['yes', 'no', 'not_applicable'].includes(value)) clean.pregnancy = value; }
    else if (key === 'alcohol') { if (['none', 'occasional', 'regular'].includes(value)) clean.alcohol = value; }
    else if (key === 'onset') { if (value === 'sudden' || value === 'gradual') clean.onset = value; }
    else if (typeof value === 'string' && value.length <= 350) clean[key] = value;
  }

  clean.lastActiveTimestamp = Date.now();
  return clean;
}

function getUpcomingQuestion(st, msg, isReset) {
  if (isReset || !st.lastQuestion || st.lastQuestion === 'consent') {
    const isAffirm = /^(?:yes|yeah|yep|sure|ok|okay|agree|oui|ja|si|نعم)/i.test(String(msg || '').trim());
    return (st.consent || isAffirm) ? 'symptom' : 'consent';
  }
  if (st.lastQuestion === 'symptom') return st.age === null ? 'age' : 'duration';
  if (st.lastQuestion === 'age') return !st.duration ? 'duration' : 'severity';
  if (st.lastQuestion === 'duration') return st.severity === null ? 'severity' : 'redflags';
  if (st.lastQuestion === 'severity') return st.redFlagsCleared !== true ? 'redflags' : 'history';
  if (st.lastQuestion === 'redflags') return 'history';
  if (st.lastQuestion === 'history') return 'summary_confirmation';
  if (st.lastQuestion === 'summary_confirmation') return 'dispense_confirmation';
  return 'symptom';
}

const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const message = typeof body.message === 'string' ? body.message.slice(0, 3000) : '';
const reset = body.reset === true;
const currentState = reset ? newState() : sanitizeState(body.state);

const rawId = typeof body.sessionId === 'string' ? body.sessionId : (typeof body.session_id === 'string' ? body.session_id : '');
const sessionId = /^[A-Za-z0-9_-]{8,64}$/.test(rawId) ? rawId : 'anon-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 10);

const upcoming = getUpcomingQuestion(currentState, message, reset);

const context = { message, state: currentState, consent: body.consent === true, channel: CHANNEL, reset, sessionId, upcomingQuestion: upcoming };
